/** 语料表里一条样本的期望（门判的就是这张表本身没被改坏）。 */
export interface NoProgressCase {
  /** 事件文件名（住在 `fixtures/no-progress/`）。 */
  file: string;
  /** 该不该报（false = 这是一条**合法**的长跑，报了就是误报）。 */
  expect: "fire" | "silent";
  /** expect=fire 时，必须至少报出这条规则名（不锁死唯一规则：一条链可以同时命中多只）。 */
